def add(p,k,f,g,kind='target',lect='Odisha',note=''):
 rows.append(dict(source_unit_key=f'peterson2024turi:p{p}:inline:{k}',printed_page=p,pdf_page=p-260,form=f,gloss=g,kind=kind,lect=lect,note=note,review_status='first_reading_pending_original_review'))
def seq(p,k,forms,g,**kw):
 for i,f in enumerate(forms.split('|'),1):add(p,f'{k}-{i}',f,g,**kw)
